/* ============================================================================
   Deploy-Full-Remote.sql
   Fully self-contained deploy: the DLL bytes are embedded below as a hex
   literal, so there is NO separate .dll file to copy, rename, or keep in
   sync on the SQL Server box -- paste this whole script into SSMS connected
   to that server and run it top to bottom.

   Drops any existing MailboxReaderClr assembly/procs first, then re-creates
   everything fresh from these exact bytes -- both usp_ReadMailbox (Graph)
   and usp_ReadMailbox_EWS (on-prem EWS).

   Generated from a build containing:
     MailboxReaderClr.MailReader, MailboxReaderClr.EwsMailReader,
     MailboxReaderClr.JsonMini
   DLL size: 20992 bytes.
   ============================================================================ */

-- 1) Enable CLR (harmless to re-run if already enabled)
EXEC sp_configure 'show advanced options', 1;
RECONFIGURE;
EXEC sp_configure 'clr enabled', 1;
RECONFIGURE;
GO

-- 2) Drop dependent procs, then the assembly, if they already exist
IF OBJECT_ID('dbo.usp_ReadMailbox_EWS', 'P') IS NOT NULL
    DROP PROCEDURE dbo.usp_ReadMailbox_EWS;
GO
IF OBJECT_ID('dbo.usp_ReadMailbox', 'P') IS NOT NULL
    DROP PROCEDURE dbo.usp_ReadMailbox;
GO
IF EXISTS (SELECT 1 FROM sys.assemblies WHERE name = 'MailboxReaderClr')
    DROP ASSEMBLY MailboxReaderClr;
GO

-- 3) The DLL itself, embedded as a hex literal (no file path needed)
DECLARE @AssemblyBytes VARBINARY(MAX) = ;

DECLARE @Hash VARBINARY(64) = HASHBYTES('SHA2_512', @AssemblyBytes);

IF NOT EXISTS (SELECT 1 FROM sys.trusted_assemblies WHERE hash = @Hash)
    EXEC sys.sp_add_trusted_assembly @hash = @Hash, @description = N'MailboxReaderClr.dll (embedded, EWS build)';

CREATE ASSEMBLY MailboxReaderClr
FROM @AssemblyBytes
WITH PERMISSION_SET = EXTERNAL_ACCESS;
GO

-- 4) Recreate both stored procedures against the freshly-registered assembly

-- Graph / Exchange Online proc
CREATE PROCEDURE dbo.usp_ReadMailbox
    @TenantId      NVARCHAR(100),
    @ClientId      NVARCHAR(100),
    @ClientSecret  NVARCHAR(200) = NULL,
    @MailboxUpn    NVARCHAR(320),
    @Password      NVARCHAR(200) = NULL,
    @FolderName    NVARCHAR(100) = 'inbox',
    @Top           INT = 25,
    @UnreadOnly    BIT = 0
AS EXTERNAL NAME MailboxReaderClr.[MailboxReaderClr.MailReader].ReadMailbox;
GO

-- On-premises Exchange (EWS) proc
CREATE PROCEDURE dbo.usp_ReadMailbox_EWS
    @EwsUrl      NVARCHAR(500),
    @MailboxUpn  NVARCHAR(320),
    @Domain      NVARCHAR(100) = NULL,
    @Username    NVARCHAR(100) = NULL,
    @Password    NVARCHAR(200) = NULL,
    @FolderName  NVARCHAR(100) = 'inbox',
    @Top         INT = 25,
    @UnreadOnly  BIT = 0
AS EXTERNAL NAME MailboxReaderClr.[MailboxReaderClr.EwsMailReader].ReadMailboxEws;
GO

-- 5) Sanity check -- confirm both procs exist, are pointed at the new
--    assembly, and the assembly's create_date is from just now
SELECT
    p.name AS ProcedureName,
    a.name AS AssemblyName,
    am.assembly_class,
    am.assembly_method,
    a.create_date AS AssemblyCreateDate
FROM sys.procedures p
JOIN sys.assembly_modules am ON am.object_id = p.object_id
JOIN sys.assemblies a ON a.assembly_id = am.assembly_id
WHERE p.name IN ('usp_ReadMailbox', 'usp_ReadMailbox_EWS');

/* ============================================================================
   Example calls
   ============================================================================ */

-- Graph (app-only):
-- EXEC dbo.usp_ReadMailbox
--     @TenantId     = 'xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx',
--     @ClientId     = 'xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx',
--     @ClientSecret = 'your-client-secret-value',
--     @MailboxUpn   = 'serviceaccount@yourdomain.com',
--     @Top          = 25;

-- EWS (on-prem, default Windows identity):
-- EXEC dbo.usp_ReadMailbox_EWS
--     @EwsUrl     = 'https://webmail.yourdomain.co.za/EWS/Exchange.asmx',
--     @MailboxUpn = 'serviceaccount@yourdomain.co.za',
--     @Top        = 25;